from PIL import Image

def analyze(path):
    im = Image.open(path).convert('RGB')
    w,h = im.size
    px = im.load()
    # find dark pixels that are isolated-ish (bore) vs large black mass (gripper)
    darks = []
    for y in range(h):
        for x in range(w):
            r,g,b = px[x,y]
            if r<30 and g<30 and b<30:
                darks.append((x,y))
    print(path, "dark count", len(darks), "size", w, h)
    # sample some colors
    # find small dark components by scanning bottom half only
    # print a coarse map of darkness in bottom 200 rows
    print("  bottom region dark map (20x10 bins of lower 240 rows):")
    rows = []
    for by in range(12):
        row = []
        for bx in range(16):
            c=0
            y0 = h-240 + by*20
            x0 = bx*40
            for y in range(y0, min(h, y0+20)):
                for x in range(x0, min(w, x0+40)):
                    r,g,b = px[x,y]
                    if r+g+b < 80:
                        c+=1
            row.append(c)
        rows.append(row)
        print("   ", "".join(f"{c:4d}" for c in row))

for p in ["wrist_001","wrist_003","wrist_004","wrist_005"]:
    analyze(f"/home/robot/captures/{p}.png")
