from PIL import Image

def find_bore(path):
    im = Image.open(path)
    px = im.load()
    w,h = im.size
    # bore is a small dark disk on lighter surface, not the huge black gripper
    # strategy: pixels with lum 20-80 that have bright neighbors within 20px and are not connected to the huge dark mass
    lum = [[0]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            r,g,b=px[x,y]
            lum[y][x]=(r+g+b)//3
    # flood huge dark region lum<50 starting from center-ish
    visited=[[False]*w for _ in range(h)]
    # mark large dark components
    large=[[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            if visited[y][x] or lum[y][x]>=60:
                continue
            stack=[(x,y)]
            visited[y][x]=True
            pts=[(x,y)]
            while stack:
                cx,cy=stack.pop()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and not visited[ny][nx] and lum[ny][nx]<60:
                        visited[ny][nx]=True
                        stack.append((nx,ny))
                        pts.append((nx,ny))
            if len(pts)>500:
                for px_,py_ in pts:
                    large[py_][px_]=True
    # now find small dark blobs not in large
    visited2=[[False]*w for _ in range(h)]
    blobs=[]
    for y in range(h):
        for x in range(w):
            if visited2[y][x] or large[y][x] or lum[y][x]>=55:
                continue
            stack=[(x,y)]
            visited2[y][x]=True
            pts=[]
            while stack:
                cx,cy=stack.pop()
                pts.append((cx,cy,lum[cy][cx]))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and not visited2[ny][nx] and not large[ny][nx] and lum[ny][nx]<55:
                        visited2[ny][nx]=True
                        stack.append((nx,ny))
            if 5 < len(pts) < 800:
                cx=sum(p[0] for p in pts)/len(pts)
                cy=sum(p[1] for p in pts)/len(pts)
                blobs.append((len(pts), cx, cy, min(p[2] for p in pts)))
    blobs.sort(key=lambda b: -b[0])
    print(path, "blobs", blobs[:6])

for i in range(8,16):
    find_bore(f"/home/robot/captures/wrist_{i:03d}.png")
